from __future__ import annotations

import operator
import re
import sys

_DIV0 = "#DIV/0!"
_CYCLE = "#CYCLE!"
_FUNCS = ("SUM", "MIN", "MAX", "IF")
_CMP = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}
_TOKEN = re.compile(r"\s*(?:([0-9]+)|([A-Z]+[0-9]*)|(<>|<=|>=|[-+*/(),:=<>]))")


def _tokenize(text):
    toks = []
    text = text.rstrip()
    pos = 0
    while pos < len(text):
        m = _TOKEN.match(text, pos)
        if m is None:
            raise ValueError("bad token in formula")
        pos = m.end()
        if m.group(1) is not None:
            toks.append(("num", int(m.group(1))))
        elif m.group(2) is not None:
            toks.append(("word", m.group(2)))
        else:
            toks.append(("op", m.group(3)))
    return toks


def _expect(toks, i, op):
    if i >= len(toks) or toks[i] != ("op", op):
        raise ValueError("expected " + op)
    return i + 1


def _expr(toks, i):
    node, i = _term(toks, i)
    while i < len(toks) and toks[i] in (("op", "+"), ("op", "-")):
        op = toks[i][1]
        rhs, i = _term(toks, i + 1)
        node = ("bin", op, node, rhs)
    return node, i


def _term(toks, i):
    node, i = _unary(toks, i)
    while i < len(toks) and toks[i] in (("op", "*"), ("op", "/")):
        op = toks[i][1]
        rhs, i = _unary(toks, i + 1)
        node = ("bin", op, node, rhs)
    return node, i


def _unary(toks, i):
    if i < len(toks) and toks[i] == ("op", "-"):
        node, i = _unary(toks, i + 1)
        return ("neg", node), i
    return _atom(toks, i)


def _atom(toks, i):
    kind, val = toks[i]
    i += 1
    if kind == "num":
        return ("num", val), i
    if kind == "word":
        if val not in _FUNCS:
            return ("ref", val), i
        i = _expect(toks, i, "(")
        if val == "IF":
            return _if(toks, i)
        return _call(toks, i, val)
    if (kind, val) == ("op", "("):
        node, i = _expr(toks, i)
        return node, _expect(toks, i, ")")
    raise ValueError("unexpected token")


def _if(toks, i):
    left, i = _expr(toks, i)
    if i >= len(toks) or toks[i][0] != "op" or toks[i][1] not in _CMP:
        raise ValueError("expected comparison operator")
    op = toks[i][1]
    right, i = _expr(toks, i + 1)
    i = _expect(toks, i, ",")
    then, i = _expr(toks, i)
    i = _expect(toks, i, ",")
    other, i = _expr(toks, i)
    i = _expect(toks, i, ")")
    return ("if", op, left, right, then, other), i


def _call(toks, i, name):
    args = []
    while True:
        if toks[i][0] == "word" and toks[i + 1] == ("op", ":"):
            a = toks[i][1]
            b = toks[i + 2][1]
            c1, c2 = sorted((ord(a[0]), ord(b[0])))
            r1, r2 = sorted((int(a[1:]), int(b[1:])))
            args.append(("range", c1, c2, r1, r2))
            i += 3
        else:
            node, i = _expr(toks, i)
            args.append(node)
        if i < len(toks) and toks[i] == ("op", ","):
            i += 1
            continue
        break
    return ("call", name, args), _expect(toks, i, ")")


def _parse(text):
    toks = _tokenize(text)
    node, i = _expr(toks, 0)
    if i != len(toks):
        raise ValueError("trailing tokens in formula")
    return node


def _binop(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return _DIV0
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    active: set[str] = set()

    def value_of(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in active:
            return _CYCLE
        text = cells[name].strip()
        if not text.startswith("="):
            memo[name] = int(text)
            return memo[name]
        active.add(name)
        result = evaluate(_parse(text[1:]))
        active.discard(name)
        memo[name] = result
        return result

    def gather(args):
        vals = []
        for arg in args:
            if arg[0] == "range":
                _, c1, c2, r1, r2 = arg
                for r in range(r1, r2 + 1):
                    for c in range(c1, c2 + 1):
                        name = chr(c) + str(r)
                        if name in cells:
                            v = value_of(name)
                            if isinstance(v, str):
                                return v
                            vals.append(v)
            else:
                v = evaluate(arg)
                if isinstance(v, str):
                    return v
                vals.append(v)
        return vals

    def evaluate(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return value_of(node[1])
        if kind == "neg":
            v = evaluate(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            return _binop(node[1], left, right)
        if kind == "if":
            _, op, l_node, r_node, then_node, else_node = node
            left = evaluate(l_node)
            if isinstance(left, str):
                return left
            right = evaluate(r_node)
            if isinstance(right, str):
                return right
            branch = then_node if _CMP[op](left, right) else else_node
            return evaluate(branch)
        _, name, args = node
        vals = gather(args)
        if isinstance(vals, str):
            return vals
        if name == "SUM":
            return sum(vals)
        if not vals:
            return 0
        return min(vals) if name == "MIN" else max(vals)

    old_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old_limit, 100_000))
    try:
        return {name: value_of(name) for name in cells}
    finally:
        sys.setrecursionlimit(old_limit)
